import json
import pandas as pd

SOURCES = [
    ("source_a", lambda: pd.read_json("/data/source_a/users.json", dtype=False)),
    ("source_b", lambda: pd.read_csv("/data/source_b/users.csv", dtype=str, keep_default_na=False)),
    ("source_c", lambda: pd.read_parquet("/data/source_c/users.parquet")),
]
ALIASES = {
    "user_id": "user_id", "id": "user_id", "userId": "user_id",
    "email": "email", "email_address": "email",
    "full_name": "name", "name": "name", "userName": "name",
    "registration_date": "created_date", "created_at": "created_date", "joined": "created_date",
    "status": "status", "is_active": "active", "active": "active",
}
FIELDS = ["name", "email", "created_date", "status"]


def blank(v):
    return v is None or (isinstance(v, float) and pd.isna(v)) or (isinstance(v, str) and v.strip() == "")


def normalize(field, v):
    if blank(v):
        return None
    if field == "user_id":
        return int(float(v))
    if field == "created_date":
        return pd.to_datetime(str(v).strip()).strftime("%Y-%m-%d")
    if field == "active":
        return "active" if str(v).strip().lower() in ("true", "1", "yes", "y", "t") else "inactive"
    return str(v).strip()


def records(name, df):
    df = df.rename(columns={c: ALIASES[c] for c in df.columns if c in ALIASES})
    for row in df.to_dict("records"):
        rec = {k: normalize(k, row.get(k)) for k in ["user_id", *FIELDS, "active"] if k in row}
        if rec.get("status") is None and rec.get("active") is not None:
            rec["status"] = rec["active"]
        rec.pop("active", None)
        if rec.get("user_id") is not None:
            yield rec


by_user = {}
for name, load in SOURCES:
    for rec in records(name, load()):
        by_user.setdefault(rec["user_id"], {})[name] = rec

rows, conflicts = [], []
for uid in sorted(by_user):
    per_source = by_user[uid]
    row = {"user_id": uid}
    for field in FIELDS:
        values = {s: r[field] for s, r in per_source.items() if r.get(field) is not None}
        selected = next(iter(values.values()), None)
        row[field] = selected
        if len(set(values.values())) > 1:
            conflicts.append({"user_id": uid, "field": field, "values": values, "selected": selected})
    rows.append(row)

out = pd.DataFrame(rows, columns=["user_id", *FIELDS])
out["user_id"] = out["user_id"].astype("int64")
for f in FIELDS:
    out[f] = out[f].astype("string")
out.to_parquet("/app/merged_users.parquet", index=False)

with open("/app/conflicts.json", "w") as fh:
    json.dump({"total_conflicts": len(conflicts), "conflicts": conflicts}, fh, indent=2)
EOF
